def rule(t, A):
    k, s, f = (t['k'], t['side'], t['fill'])
    h, l = (A.h, A.l)
    lim = t['ku'] - 1
    for j in range(max(2, k - 180), min(k - 2, lim)):
        if s < 0:
            if l[j] <= l[j - 1] and l[j] <= l[j - 2] and (l[j] <= l[j + 1]) and (l[j] <= l[j + 2]) and (abs(f - l[j]) <= 3e-05):
                return True
        elif h[j] >= h[j - 1] and h[j] >= h[j - 2] and (h[j] >= h[j + 1]) and (h[j] >= h[j + 2]) and (abs(f - h[j]) <= 3e-05):
            return True
    return False

def rule(t, A):
    k, s = (t['k'], t['side'])
    a = A.atr[k]
    if not a > 0:
        return False
    for j in range(k - 2, k + 1):
        if (A.c[j] - A.o[j]) * -s > 0 and A.h[j] - A.l[j] >= 2.5 * a:
            return True
    return False

def rule(t, A):
    k, s = (t['k'], t['side'])
    h, l = (A.h, A.l)
    hs, ls = ([], [])
    for j in range(max(2, k - 120), k - 1):
        if h[j] >= h[j - 1] and h[j] >= h[j - 2] and (h[j] >= h[j + 1]) and (h[j] >= h[j + 2]):
            hs.append(h[j])
        if l[j] <= l[j - 1] and l[j] <= l[j - 2] and (l[j] <= l[j + 1]) and (l[j] <= l[j + 2]):
            ls.append(l[j])
    if len(hs) < 2 or len(ls) < 2:
        return False
    if s > 0:
        return hs[-1] < hs[-2] and ls[-1] < ls[-2]
    return hs[-1] > hs[-2] and ls[-1] > ls[-2]
